result.args:
位置参数数组：[input: {
    /** 当前目标中完整模型的根身份。 */
    root: NodeHandle;
    /** 可选检查类别；省略返回全部。 */
    kind?: "node" | "component" | "binding" | "reference";
}, options?: {
    /** 请求的最大条数，必须为正安全整数，默认 100；不设置固定条数或单页字节数上限。 */
    limit?: number;
    /** 上一页的 nextCursor，原样传回；继续分页时保留同一目标、筛选和投影，编辑或查询变化后须从头读取。 */
    cursor?: string;
    /** 可选返回字段键；省略使用方法默认投影，空数组表示不取行字段。是否支持行投影以方法签名为准。 */
    fields?: ("kind" | "node" | "path" | "nodeInfo" | "transform" | "componentType" | "values" | "binding" | "reference")[];
}]
args[0] input: 完整模型根和可选检查类别；只读取当前保存状态，不计算历史差异。
args[1] options: 分页与可选投影，limit 默认为 100，须为正安全整数，无固定上限；修改场景后重新开始分页。
类型约定：
NodeHandle：当前文档中的节点身份；文档 ID 不变则句柄不变，ID 复用后定位新节点。
WPrefab 宿主返回 n12，直接来自文档 node.id；目标由外层操作选择，不是 Unity GetInstanceID()。

result.returns:
{
    /** 本页实际返回的记录，字段范围以请求投影为准；即使不足 limit，也应检查 nextCursor 是否仍有后续。 */
    items: Partial<{
        /** 当前记录类别：node/component/binding/reference。 */
        kind: "node" | "component" | "binding" | "reference";
        /** 被检查的树内节点；整树替换后失效，不能用于编辑新模型。 */
        node: NodeHandle;
        /** 相对模型根的节点名称数组，根为空数组；可能重名，不作为唯一身份。 */
        path: string[];
        /** node 行的当前完整节点属性；不表示这些属性均由人工修改。 */
        nodeInfo?: {
            /** 当前文档中的节点句柄；WPrefab 使用 n<node.id>，ID 复用后定位新节点，不按显示名查找。 */
            handle: NodeHandle;
            /** 保存的节点显示名；允许重名，定位时结合 parent/subtree 等条件，不把名称当唯一身份。 */
            name: string;
            /** 父节点身份；场景根节点为 null。改变父级请使用 nodes.reparent，不直接修改此返回值。 */
            parent: NodeHandle | null;
            /** 节点保存的 isActive 开关；表示节点自身的活动配置，不是包含所有祖先影响后的最终运行状态。 */
            active: boolean;
            /** Unity Layer 编号，范围 0..31；不是 Layer 显示名称。 */
            layer: number;
            /** Unity Tag 字符串；新建节点默认为 Untagged，最终可用 Tag 受当前 Runtime 配置约束。 */
            tag: string;
            /** 从场景根开始的层级深度；根节点为 0，父子层级每深入一级加 1。 */
            depth: number;
            /** 节点实际存在的组件字段键列表，例如 physicsColliderData；不包含完整组件值，详情使用 components.get。 */
            componentTypes: string[];
            /** 纯锚点的触控用途标记；无标记时为 null，存在标记不代表已经生成拾取/乘坐玩法脚本。 */
            interactionPoint: {
                /** 触控用途：PickUp 表示拾取锚点，Seat 表示座位锚点；它是编辑元数据，不会自动创建 Trigger 或脚本。 */
                kind: "PickUp" | "Seat";
            } | null;
            /** 宿主预览使用的 Runtime 数字节点 ID，只读；外层工具需要数字 ID 时可使用，SDK 编辑仍要求 handle。 */
            previewNodeId: number;
        };
        /** node 行相对于当前父节点的局部 TRS；位置为 Unity 米，旋转为 xyzw 四元数。 */
        transform?: {
            /** 所选 space 中的位置，单位为米；local 相对于父节点，world 相对于世界原点。 */
            position: {
                /** X 分量，必须为有限数；位置/平移使用米，缩放使用无单位倍率，作为缩放时不能为零。 */
                x: number;
                /** Y 分量，必须为有限数；Unity 的向上轴为 Y，位置/平移使用米，缩放使用无单位倍率。 */
                y: number;
                /** Z 分量，必须为有限数；位置/平移使用米，缩放使用无单位倍率，作为缩放时不能为零。 */
                z: number;
            };
            /** 所选 space 中的单位四元数，分量顺序为 xyzw；不能传欧拉角。 */
            rotation: {
                /** 四元数向量部分的 X 分量，无单位；与 y/z/w 共同构成归一化旋转，不是以米为单位的位置。 */
                x: number;
                /** 四元数向量部分的 Y 分量，无单位；表示旋转分量，不是欧拉角或 Y 轴平移。 */
                y: number;
                /** 四元数向量部分的 Z 分量，无单位；必须与其它分量一起有限且归一化。 */
                z: number;
                /** 单位四元数的标量分量；与 x/y/z 一起满足归一化约束，单位旋转为 {x:0,y:0,z:0,w:1}。 */
                w: number;
            };
            /** 所选 space 中的缩放，无单位；local 为局部缩放，world 为有符号 lossyScale，分量不能为零。 */
            scale: {
                /** X 分量，必须为有限数；位置/平移使用米，缩放使用无单位倍率，作为缩放时不能为零。 */
                x: number;
                /** Y 分量，必须为有限数；Unity 的向上轴为 Y，位置/平移使用米，缩放使用无单位倍率。 */
                y: number;
                /** Z 分量，必须为有限数；位置/平移使用米，缩放使用无单位倍率，作为缩放时不能为零。 */
                z: number;
            };
        };
        /** component 行的组件字段键；具体字段规则通过 components.schema 查询。 */
        componentType?: string;
        /** component 行的当前保存值，与 components.get 一致；内部数字引用不能直接迁移到新节点。 */
        values?: JsonValue;
        /** binding 行的脚本身份及独立参数；旧绑定失效后可复用脚本定义重新 bind。 */
        binding?: {
            /** Runtime 是否执行此绑定；未显式禁用的历史绑定返回 true。 */
            enabled: boolean;
            /** 该绑定声明的作用域角色；普通业务绑定为 null，可据此核对 Host/Resource 边界。 */
            scopeRole: ("resource" | "host") | null;
            /** 当前节点上这条绑定的句柄，供 setParams/unbind 使用；WPrefab 使用 n<node.id>:s:<scriptId>。 */
            handle: BindingHandle;
            /** 承载该绑定的节点身份；同一 Lua 定义可以被多个节点独立绑定。 */
            node: NodeHandle;
            /** 被绑定的 Lua 定义身份；修改该定义的源码会影响所有引用它的绑定。 */
            script: ScriptHandle;
            /** 源码相对当前文档根目录的实际路径；系统内联定义或登记缺失时为 null，源码丢失仍保留登记路径。 */
            filePath: string | null;
            /** 该节点实例独立保存的 JSON 参数对象；与源码定义分离，参数约束以 Lua 注解 schema 为准。 */
            params: JsonObject;
            /** 是否为 RuntimeScope 等宿主管理的只读绑定；此类绑定不能独立 setParams 或 unbind。 */
            readonly: boolean;
        };
        /** reference 行的树外引用者及字段位置；替换前须处理，不包含树内相互引用。 */
        reference?: {
            /** 持有该引用的节点、脚本或文档来源；document 来源没有 handle，不要假定所有来源都是节点。 */
            owner: ({
                /** 引用目标的判别类型：node/script/resource；必须与 handle 的品牌一致，document 仅用于引用来源。 */
                $ref: "node";
                /** 与 $ref 匹配的目标身份；从对应 SDK 查询结果取得，当前目标中不存在对应 ID 时拒绝。 */
                handle: NodeHandle;
            } | {
                /** 引用目标的判别类型：node/script/resource；必须与 handle 的品牌一致，document 仅用于引用来源。 */
                $ref: "script";
                /** 与 $ref 匹配的目标身份；从对应 SDK 查询结果取得，当前目标中不存在对应 ID 时拒绝。 */
                handle: ScriptHandle;
            } | {
                /** 引用目标的判别类型：node/script/resource；必须与 handle 的品牌一致，document 仅用于引用来源。 */
                $ref: "resource";
                /** 与 $ref 匹配的目标身份；从对应 SDK 查询结果取得，当前目标中不存在对应 ID 时拒绝。 */
                handle: ResourceHandle;
            }) | {
                /** 文档级引用来源固定为 document；它描述场景级字段，不携带节点、脚本或资源句柄。 */
                $ref: "document";
            };
            /** 该来源中引用所在的 DTO 字段路径或 require 行定位，用于先解除引用再安全删除目标。 */
            field: string;
        };
    }>[];
    /** 是否仍有未返回的记录；为 true 时使用 nextCursor 继续读取，不表示场景或源码被截断保存。 */
    truncated: boolean;
    /** 存在后续记录时返回的游标；缺省表示已读完，不能解析、拼接或跨查询复用。 */
    nextCursor?: string;
}
当前配置分页；大组件可先投影 componentType，再用 components.get 按内部字段补读，脚本源码通过 bindings 的 filePath 由宿主文件工具读取。
未指定字段投影时返回完整检查行；各类别的专用字段仍可能缺省。
类型约定：
JsonValue：可穿过 SDK 调用边界的 JSON 数据；不允许函数、undefined 或宿主对象。
JsonObject：动态组件与脚本参数的 JSON 对象；字段规则由当前 schema 决定。
NodeHandle：当前文档中的节点身份；文档 ID 不变则句柄不变，ID 复用后定位新节点。
WPrefab 宿主返回 n12，直接来自文档 node.id；目标由外层操作选择，不是 Unity GetInstanceID()。
ScriptHandle：Lua 定义身份；不能代替节点或绑定身份。
WPrefab 宿主返回实际脚本 ID，不带前缀；handle 与 id 相同，可从 Lua 头部的 ID 注解读取。未挂载 builtin 使用供给方永久 ID。
ResourceHandle：资源来源身份；远程值为固定 URI，包内值为 r12，直接来自当前文档 resourceRefs 中的 ID。
BindingHandle：一个节点上的脚本绑定身份；同一脚本的不同绑定拥有独立参数。
WPrefab 宿主返回 n12:s:<scriptId>，直接由节点 ID 和 binding.scriptId 组合；解绑再绑定同一脚本时相同。
